export type SlotApiRequestType = 'PING' | 'SLOT_SPIN' | 'SLOT_GET_GAME' | 'GET_GAME_INFO' | 'GET_BET_HISTORY' | 'GET_BET_DETAIL' | 'GET_GAME_STATE' | 'GET_JACKPOT_POOL' | 'SUBSCRIBE_JACKPOT_POOL' | 'UNSUBSCRIBE_JACKPOT_POOL';

export const SLOT_API_RESPONSE_TYPE = {
    PONG: 'PONG',
    SLOT_SPIN_RESPONSE: 'SLOT_SPIN_RESPONSE',
    GET_GAME_INFO_RESPONSE: 'GET_GAME_INFO_RESPONSE',
    GET_BET_HISTORY_RESPONSE: 'GET_BET_HISTORY_RESPONSE',
    GET_BET_DETAIL_RESPONSE: 'GET_BET_DETAIL_RESPONSE',
    GET_GAME_STATE_RESPONSE: 'GET_GAME_STATE_RESPONSE',
    GET_JACKPOT_POOL_RESPONSE: 'GET_JACKPOT_POOL_RESPONSE',
    SUBSCRIBE_JACKPOT_POOL_RESPONSE: 'SUBSCRIBE_JACKPOT_POOL_RESPONSE',
    UNSUBSCRIBE_JACKPOT_POOL_RESPONSE: 'UNSUBSCRIBE_JACKPOT_POOL_RESPONSE',
    SLOT_GET_GAME_RESPONSE: 'SLOT_GET_GAME_RESPONSE',
    JACKPOT_POOL_UPDATE: 'JACKPOT_POOL_UPDATE',
    ACK: 'ACK',
} as const;

export type SlotApiResponseType = (typeof SLOT_API_RESPONSE_TYPE)[keyof typeof SLOT_API_RESPONSE_TYPE];

export type SlotApiFrameType = SlotApiRequestType | SlotApiResponseType;

/** 已知 ACK code 並允許後端擴充 */
export type SlotApiErrorCode = 'BAD_PAYLOAD' | 'UNKNOWN_FRAME_TYPE' | 'SLOT_ERR' | 'SLOT_SPIN_FAILED' | 'SLOT_GET_GAME_FAILED' | 'GET_GAME_INFO_FAILED' | 'GET_BET_HISTORY_FAILED' | 'GET_BET_DETAIL_FAILED' | 'GET_GAME_STATE_FAILED' | 'SLOT_V1_REMOVED' | 'JACKPOT_UNSUPPORTED_GAME' | 'CURRENCY_NOT_CONFIGURED' | 'JACKPOT_POOL_INCOMPLETE' | 'JACKPOT_POOL_UNAVAILABLE' | (string & {});

export interface SlotApiError {
    code: SlotApiErrorCode;
    message: string;
    numeric_code?: number;
}

export interface SlotApiFrame<TPayload = unknown> {
    type: SlotApiFrameType;
    correlation_id?: string;
    ts_ms?: number;
    payload?: TPayload;
    error?: SlotApiError;
}

