const DEFAULT_DEBUG_NORMAL_SYMBOLS: [number, string][] = Array.from({ length: 9 }, (_, i) => [i + 1, `sym${i + 1}`]);

export function getSymbolDebugOptions(symbols?: SlotApiSymbolInfo[] | null): [number, string][] {
    const normals = (symbols ?? []).filter((s) => s.kind === 'normal');
    if (normals.length === 0) return DEFAULT_DEBUG_NORMAL_SYMBOLS;
    return normals
        .slice()
        .sort((a, b) => a.id - b.id)
        .map((s) => [s.id, s.name]);
}
