export interface IGameMain {
    /** 是否已註冊某個狀態 */
    hasState(stateKey: string): boolean;

    /** 取得目前狀態 key，尚未進入任何狀態時回傳 null */
    getCurStateKey(): string | null;

    /** 切換狀態：呼叫目前狀態的 exit()，再呼叫目標狀態的 enter() */
    changeState(stateKey: string): void;
}

/**
 * GameState（共用基底，純 TS 類別，非 Cocos Component）
 *
 * 比照舊專案（Cocos_2022）SGEngine 的 SGState_NG/SGState_FG：狀態本身刻意保持空殼，
 * 真正的進場/離場side effect（UI 切換、背景轉場等）仍由既有的 GameTask 流程
 * （例如 EnterFreeGameTask/ExitFreeGameTask）負責，changeState() 只是流程中的
 * 其中一步——這點跟舊專案一致（SGState_NG/FG 的 onEnter/onExit 也都是空的，
 * 實際邏輯在 GameMain 其他地方）。
 *
 * 舊專案 GameState 是掛在場景節點上的 Cocos Component（透過 InitStates() 遍歷
 * statesNode 底下的子節點取得）；entry 目前無此編輯器慣例，改用單純的 TS 類別
 * 實體（`new NGState_1001()`），由各遊戲的 GameMain_<gameId> 在 gameInit() 內
 * 直接建立並註冊，不需要額外的場景節點/prefab 改動。
 *
 * 使用方式：各遊戲繼承本類別實作自己的狀態（例如 `NGState_1001 extends
 * GameState<GameMain_1001>`），泛型 TGame 讓子類別的 `this.game` 直接拿到
 * 強型別的具體 GameMain，不必每次都轉型。
 */
export abstract class GameState<TGame extends IGameMain = IGameMain> {
    protected game!: TGame;

    /** 註冊時呼叫一次，注入 game 參考 */
    public init(game: TGame): void {
        this.game = game;
        this.onInit();
    }

    /** 進入此狀態 */
    public enter(): void {
        this.onEnter();
    }

    /** 離開此狀態 */
    public exit(): void {
        this.onExit();
    }

    protected onInit(): void {}
    protected onEnter(): void {}
    protected onExit(): void {}
}
