export type EventDisposer = () => void;
export type EventHandler<TPayload> = (payload: TPayload) => void;

export interface EventBusOptions {
    /** 未設定時不輸出 log */
    debugName?: string;
    /** 事件仍正常派送，只略過指定事件的除錯輸出 */
    debugIgnoredEvents?: readonly PropertyKey[];
}

/**
 * - EventBus 不保存目前狀態
 * - emit 使用 listener 快照；listener 可解除
 * - 同一 event 可有多個 listener
 * - listener 的錯誤由呼叫端決定
 */
export class TypedEventBus<TEvents extends object> {
    private readonly listeners = new Map<keyof TEvents, Set<EventHandler<unknown>>>();

    constructor(private readonly options: EventBusOptions = {}) {}

    on<K extends keyof TEvents>(type: K, handler: EventHandler<TEvents[K]>): EventDisposer {
        let registeredHandlers = this.listeners.get(type);
        if (!registeredHandlers) {
            registeredHandlers = new Set<EventHandler<unknown>>();
            this.listeners.set(type, registeredHandlers);
        }
        const handlers = registeredHandlers;

        const storedHandler = handler as unknown as EventHandler<unknown>;
        handlers.add(storedHandler);
        let active = true;

        return () => {
            if (!active) return;
            active = false;
            handlers.delete(storedHandler);
            if (handlers.size === 0) this.listeners.delete(type);
        };
    }

    once<K extends keyof TEvents>(type: K, handler: EventHandler<TEvents[K]>): EventDisposer {
        let dispose: EventDisposer = () => undefined;
        dispose = this.on(type, (payload) => {
            dispose();
            handler(payload);
        });
        return dispose;
    }

    emit<K extends keyof TEvents>(type: K, payload: TEvents[K]): void {
        const handlers = this.listeners.get(type);
        const shouldDebug = Boolean(
            this.options.debugName
            && !this.options.debugIgnoredEvents?.includes(type as PropertyKey),
        );
        if (shouldDebug) {
            console.log(
                `[EventBus:${this.options.debugName}] emit`,
                String(type),
                `listeners=${handlers?.size ?? 0}`,
                payload,
            );
        }
        if (!handlers) return;

        // 用 Array.from 而非 [...handlers]：web build 的 bundler 曾把 Set 的展開語法
        // 誤轉譯成 [].concat(handlers)，導致整個 Set 被當成單一個「handler」呼叫
        // （TypeError: xxx is not a function）。Array.from 是一般函式呼叫，不受編譯
        // 目標影響，能穩定把 Set 轉成陣列。
        for (const handler of Array.from(handlers)) {
            if (shouldDebug) {
                console.log(`[EventBus:${this.options.debugName}] dispatch`, String(type));
            }
            handler(payload);
        }
    }

    /** 清除指定 event；省略時清除全部 listener */
    clear(type?: keyof TEvents): void {
        if (type === undefined) {
            this.listeners.clear();
            return;
        }
        this.listeners.delete(type);
    }

    /** 返回指定 event 的數量；省略時返回全部 */
    listenerCount(type?: keyof TEvents): number {
        if (type !== undefined) return this.listeners.get(type)?.size ?? 0;

        let count = 0;
        for (const handlers of this.listeners.values()) count += handlers.size;
        return count;
    }
}
