import { TypedEventBus } from "../../events/TypedEventBus";
import type { TableListEntry } from "./TableListViewModel";

export interface TableListSelectionEvents {
    /** 選中桌位變動（含取消選取，entry 為 null） */
    selectedChanged: { entry: TableListEntry | null };
}

/**
 * TableListSelection（模組級單例）
 *
 * 管理桌列表目前選中哪一桌，純 UI/session 層面的狀態，跟 TableListModel
 * （桌位真實資料）職責分開。刻意不透過 VirtualList 的 bind(data, index) 傳遞
 * 選中狀態，避免 VirtualList 這個通用元件被桌列表這個具體業務綁死——
 * TableListItemView/TableListDetailPanel/TableListSceneController 各自訂閱
 * 這裡的事件即可，不需要额外的傳遞路徑。
 *
 * 比照 PendingGameEntry 的 static class 單例寫法，但因為選中狀態需要被
 * 多方即時反應（高亮/詳細面板/捲動定位都要同步更新），所以額外帶一個
 * TypedEventBus。
 */
export class TableListSelection {
    static readonly events = new TypedEventBus<TableListSelectionEvents>();

    private static current: TableListEntry | null = null;

    static select(entry: TableListEntry | null): void {
        if (this.current?.identity.tableId === entry?.identity.tableId) return;
        this.current = entry;
        this.events.emit("selectedChanged", { entry });
    }

    static getSelected(): TableListEntry | null {
        return this.current;
    }

    /** 離開桌列表場景時呼叫，避免下次進來殘留上次選中的桌位 */
    static clear(): void {
        this.select(null);
    }
}
