import { DEBUG, EDITOR, NATIVE } from 'cc/env';
import { native } from 'cc';

export interface ConfigType {
    Env: string;
    mock?: boolean;
    /** 大廳 REST API base path，見 assets/lobby/api/ApiConfig.ts */
    lobbyApiBaseUrl?: string;
    /** 大廳客服/聊天 Socket.IO 連線網址，見 FrontendSocketService.ts */
    frontendSocketUrl?: string;
    /** 遊戲 SlotApi HTTP 連線網址，見 HttpClientStore.ts */
    gameHttpBaseUrl?: string;
    /** 遊戲 SlotApi WebSocket 連線網址，見 HttpClientStore.ts */
    gameWsUrl?: string;
}
export class GameConfig {
    public static userId: string | null = '';
    public static code: string | null = '';
    public static language: string | null = '';
    public static currency: string | null = '';
    public static auth: string | null = '';
    public static scenario: string | null = '';
    public static base: string | null = 'base';
    public static urlParams: URLSearchParams | null = null;

    public static config: ConfigType | null = null;

    public static initUrlParams(): void {
        // Native 環境 (Android/iOS) 沒有 location 和 URLSearchParams
        if (NATIVE) {
            this.code = this.code || 'lobby';
            this.language = this.language || 'zh-HK';
            return;
        }

        const { hash, search } = globalThis.location;
        const decodeSearch = hash.startsWith('#') ? atob(hash.slice(1)) : search;

        const urlParams = (this.urlParams = new URLSearchParams(decodeSearch));
        const requestedCode = urlParams.get('game') ?? urlParams.get('code');
        this.code = requestedCode === 'sethg' || requestedCode === '1001' || requestedCode === 'GameScene' ? 'lobby' : (requestedCode ?? (this.code || 'lobby'));
        this.language = urlParams.get('language') ?? this.language ?? 'zh-HK';
        this.currency = urlParams.get('currency') ?? this.currency;
        this.auth = urlParams.get('auth') ?? this.auth;
        this.userId = urlParams.get('userid') ?? this.userId;
        this.scenario = urlParams.get('scenario') ?? this.scenario;
    }

    public static async initBuildConfig(): Promise<void> {
        if (EDITOR) {
            return;
        }

        // Native 環境使用 FileUtils 讀取檔案
        if (NATIVE) {
            try {
                const configPath = native.fileUtils.fullPathForFilename('config/config.json');
                if (configPath) {
                    const content = native.fileUtils.getStringFromFile(configPath);
                    if (content) {
                        this.config = JSON.parse(content);
                    }
                }
            } catch (err) {
                console.warn('Native: Failed to load config:', err);
            }
            return;
        }

        // Web 環境使用 fetch
        this.config = await globalThis
            .fetch('config/config.json')
            .then((res) => {
                if (!res.ok) {
                    throw new Error(`Failed to fetch config: ${res.statusText}`);
                }
                return res.json();
            })
            .catch((err) => {
                console.error('Failed to fetch config:', err);
                return null;
            });
    }
}

export const isMock = (): boolean => {
    // Native 環境從 config.json 讀取
    if (NATIVE) {
        return GameConfig.config?.mock === true;
    }
    const searchParams = new URL(globalThis.location.href).searchParams;
    return searchParams.has('scenario') || searchParams.get('mock') === 'true';
};

/**
 * 後端異常時是否允許自動切換 mock
 * 連線失敗的 fallback 時 環境為僅限測試/開發為 true 正式環境 false
 */
export const autoFallbackToMock = (): boolean => true; // DEBUG

await GameConfig.initBuildConfig();
GameConfig.initUrlParams();
